//! Port of `tests/cli/logit_sampler_test.cpp` (with the shared
//! `tests/models/qwen27b/sampling_cases.hpp`), plus the differential check
//! against the C++ sampler's recorded output (`fixtures/sampling_cpp.json`,
//! regenerated by `tests/reference/cpp_sampling_dump.cpp`).

use std::sync::Arc;

