use gufo_core::text::ErrorKind;

struct SamplingCase {
    name: &'static str,
    config: SamplingConfig,
}

fn config(temperature: f32) -> SamplingConfig {
    SamplingConfig {
        temperature,
        ..SamplingConfig::default()
    }
}

