fn sampler(config: SamplingConfig, history: &[TokenId]) -> SamplerState {
    SamplerState::new(config, history).expect("sampler")
}

fn build(logits: &[f32], config: &SamplingConfig) -> SamplingDistribution {
    build_distribution(logits, config, &[], &[]).expect("distribution")
}

#[test]
fn uniform_is_half_open_with_53_bits() {
    let mut sub_float_resolution = false;
    for seed in 1u64..100 {
        let mut state = seed;
        let mut reference = seed;
        let bits = next_random(&mut reference);
        let draw = uniform(&mut state);
        assert!(
            (0.0..1.0).contains(&draw) && state == reference,
            "uniform stays half-open and consumes one RNG word"
        );
        assert_eq!(
            draw,
            (bits >> 11) as f64 * 2f64.powi(-53),
            "uniform retains all 53 random mantissa bits"
        );
        sub_float_resolution |= draw != f64::from(draw as f32);
    }
    assert!(sub_float_resolution, "uniform must exceed float resolution");
}

#[test]
fn greedy_selects_finite_argmax_without_advancing_rng() {
    let logits = [-1.0, 5.0, f32::NAN, 2.0];
    let mut rng_state = 1234;
    let token = sample_logits(&logits, 0.0, Some(&mut rng_state)).expect("sample");
    assert_eq!(token, 1, "greedy sampling selects the finite argmax");
    assert_eq!(
        rng_state, 1234,
        "greedy sampling does not consume RNG state"
    );
}

#[test]
fn default_config_preserves_greedy_decoding() {
    let logits = [-1.0, 5.0, 3.0, 2.0];
    let mut sampler = SamplerState::default();
    let before = sampler.rng_state();
    let token = sampler.sample(&logits).expect("sample");
    assert_eq!(token, 1, "default sampler is greedy");
    assert_eq!(
        sampler.rng_state(),
        before,
        "default sampler does not consume RNG state"
    );
}

#[test]
fn temperature_sampling_is_deterministic_and_non_greedy() {
    let logits = [0.0, 0.0, 0.0];
    let (mut saw_first, mut saw_non_first) = (false, false);
    for seed in 1u64..=128 {
        let (mut left_state, mut right_state) = (seed, seed);
        let left = sample_logits(&logits, 1.0, Some(&mut left_state)).expect("sample");
        let right = sample_logits(&logits, 1.0, Some(&mut right_state)).expect("sample");
        assert!(
            left == right && left_state == right_state,
            "temperature sampling is reproducible from the same RNG state"
        );
        saw_first |= left == 0;
        saw_non_first |= left != 0;
    }
    assert!(
        saw_first && saw_non_first,
        "temperature sampling does not collapse to greedy argmax"
    );
}

#[test]
fn top_k_filters_the_candidate_set() {
    let logits = [5.0, 4.0, 3.0, 2.0, 1.0];
    let distribution = build(
        &logits,
        &SamplingConfig {
            top_k: 2,
            ..config(1.0)
        },
    );
    assert_eq!(
        distribution.entries().len(),
        2,
        "top-k retains exactly k candidates"
    );
    assert!(
        distribution.probability(0) > 0.0 && distribution.probability(1) > 0.0,
        "top-k retains the highest-logit candidates"
    );
    assert_eq!(
        distribution.probability(2),
        0.0,
        "top-k removes lower-logit candidates"
    );
}

#[test]
fn top_p_filters_by_cumulative_probability() {
    let distribution = build(
        &[3.0, 2.0, 1.0],
        &SamplingConfig {
            top_p: 0.7,
            ..config(1.0)
        },
    );
    assert_eq!(
        distribution.entries().len(),
        2,
        "top-p retains the smallest cumulative-probability prefix"
    );
    assert_eq!(
        distribution.probability(2),
        0.0,
        "top-p removes the low-probability tail"
    );
}

#[test]
fn min_p_filters_relative_to_the_best_token() {
    let distribution = build(
        &[3.0, 2.4, 1.0],
        &SamplingConfig {
            min_p: 0.5,
            ..config(1.0)
        },
    );
    assert_eq!(
        distribution.entries().len(),
        2,
        "min-p retains candidates above the relative threshold"
    );
    assert_eq!(
        distribution.probability(2),
        0.0,
        "min-p removes candidates far below the best token"
    );
}

#[test]
fn min_keep_provides_a_filter_floor() {
    let distribution = build(
        &[5.0, 4.0, 3.0, 2.0],
        &SamplingConfig {
            top_k: 1,
            top_p: 0.1,
            min_p: 0.99,
            min_keep: 3,
            ..config(1.0)
        },
    );
    assert_eq!(
        distribution.entries().len(),
        3,
        "min-keep prevents enabled filters from shrinking below its floor"
    );
}

#[test]
fn temperature_before_probability_filters() {
    // Closed-form expectations for softmax([0,-1,-2] / T); 2048 also
    // exercises the bounded (>1024 vocabulary) candidate selector.
    for size in [3usize, 2048] {
        let mut logits = vec![-1000.0f32; size];
        logits[0] = 0.0;
        logits[1] = -1.0;
        logits[2] = -2.0;
        for nucleus in [false, true] {
            let mut c = SamplingConfig {
                seed: 42,
                ..config(0.5)
            };
            if nucleus {
                c.top_p = 0.8;
            } else {
                c.min_p = 0.2;
            }
            let mut s = sampler(c.clone(), &[]);
            for distribution in [
                build(&logits, &c),
                s.distribution(&logits).expect("distribution"),
            ] {
                assert!(
                    distribution.entries().len() == 1 && distribution.probability(0) == 1.0,
                    "temperature sharpens probabilities before filtering"
                );
            }
            for _ in 0..32 {
                assert_eq!(
                    s.sample(&logits).expect("sample"),
                    0,
                    "ordinary decode uses the tempered candidate set"
                );
            }
            c.temperature = 2.0;
            c.top_p = if nucleus { 0.8 } else { 1.0 };
            c.min_p = if nucleus { 0.0 } else { 0.5 };
            let first = 1.0 / (1.0 + (-0.5f64).exp());
            for distribution in [
                build(&logits, &c),
                sampler(c.clone(), &[])
                    .distribution(&logits)
                    .expect("distribution"),
            ] {
                assert!(
                    distribution.entries().len() == 2
                        && (distribution.probability(0) - first).abs() < 1e-12
                        && (distribution.probability(1) - (1.0 - first)).abs() < 1e-12,
                    "temperature flattens probabilities before filtering"
                );
            }
        }
    }
}

#[test]
fn repeat_penalty_uses_committed_history() {
    let c = SamplingConfig {
        repeat_penalty: 3.0,
        ..SamplingConfig::default()
    };
    let distribution = build_distribution(&[2.0, 1.0, 0.0], &c, &[0], &[]).expect("distribution");
    assert_eq!(
        distribution.best_token().expect("best"),
        1,
        "repeat penalty can demote a recently used token"
    );
}

#[test]
fn frequency_and_presence_penalties_use_counts() {
    let logits = [2.0, 1.4];
    let history = [0, 0];
    let frequency = SamplingConfig {
        frequency_penalty: 0.4,
        ..SamplingConfig::default()
    };
    assert_eq!(
        build_distribution(&logits, &frequency, &[], &history)
            .expect("distribution")
            .best_token()
            .expect("best"),
        1,
        "frequency penalty scales with occurrence count"
    );
    let presence = SamplingConfig {
        presence_penalty: 0.7,
        ..SamplingConfig::default()
    };
    assert_eq!(
        build_distribution(&logits, &presence, &[], &history)
            .expect("distribution")
            .best_token()
            .expect("best"),
        1,
        "presence penalty applies once when a token is present"
    );
}

#[test]
fn repeat_window_is_bounded() {
    let c = SamplingConfig {
        repeat_penalty: 2.0,
        repeat_last_n: 1,
        ..SamplingConfig::default()
    };
    let distribution = build_distribution(&[2.0, 2.1], &c, &[0, 1], &[]).expect("distribution");
    assert_eq!(
        distribution.best_token().expect("best"),
        0,
        "repeat-last-n excludes tokens outside the configured window"
    );
}

#[test]
fn fast_greedy_matches_normalized_penalty_route() {
    let logits = [3.0, 2.9, 2.8, 2.7, 2.6];
    let history = [0, 0, 1, 3];
    let c = SamplingConfig {
        repeat_penalty: 1.5,
        frequency_penalty: 0.2,
        presence_penalty: 0.1,
        ..SamplingConfig::default()
    };
    let mut s = sampler(c.clone(), &history);
    let expected = build_distribution(&logits, &c, &history, &[])
        .expect("distribution")
        .best_token()
        .expect("best");
    assert_eq!(
        s.sample(&logits).expect("sample"),
        expected,
        "linear greedy route matches the normalized penalty route"
    );
}

#[test]
fn fast_top_k_sampling_never_escapes_selected_set() {
    let logits = [8.0, 7.0, 1.0, 0.0, -1.0, -2.0];
    let (mut saw_first, mut saw_second) = (false, false);
    for seed in 1i64..=256 {
        let c = SamplingConfig {
            top_k: 2,
            seed,
            ..config(1.0)
        };
        let token = sampler(c.clone(), &[]).sample(&logits).expect("sample");
        assert!(
            token <= 1,
            "top-k fast route retains only selected candidates"
        );
        saw_first |= token == 0;
        saw_second |= token == 1;
    }
    assert!(
        saw_first && saw_second,
        "top-k fast route samples the retained distribution"
    );
}

#[test]
fn fast_min_p_sampling_never_escapes_relative_threshold() {
    let logits = [3.0, 2.5, 1.0, -4.0];
    for seed in 1i64..=256 {
        let c = SamplingConfig {
            min_p: 0.5,
            seed,
            ..config(1.0)
        };
        assert!(
            sampler(c.clone(), &[]).sample(&logits).expect("sample") <= 1,
            "min-p linear route rejects tokens below the relative threshold"
        );
    }
}

#[test]
fn seed_and_state_are_request_local() {
    let logits = [0.0, 0.0, 0.0];
    let c = SamplingConfig {
        seed: 42,
        repeat_last_n: 2,
        ..config(1.0)
    };
    let mut left = sampler(c.clone(), &[]);
    let mut right = sampler(c.clone(), &[]);
    for _ in 0..16 {
        assert_eq!(
            left.sample(&logits).expect("sample"),
            right.sample(&logits).expect("sample"),
            "equal seeds produce equal token sequences"
        );
    }
    for token in [1, 2, 0] {
        left.accept(token).expect("accept");
    }
    assert_eq!(
        left.history(),
        [2, 0],
        "sampler retains only its bounded committed history"
    );
    assert!(
        right.history().is_empty(),
        "sampler histories are request-local"
    );
}

#[test]
fn distribution_is_normalized() {
    let distribution = build(&[2.0, 1.0, 0.0, -1.0], &config(0.8));
    let sum: f64 = distribution.entries().iter().map(|e| e.value).sum();
    assert!(
        (sum - 1.0).abs() < 1e-12,
        "post-filter probabilities are normalized"
    );
}

#[test]
fn sampling_fails_closed_on_invalid_inputs() {
    let mut rng_state = 1;
    let error = sample_logits(&[], 1.0, Some(&mut rng_state)).expect_err("empty");
    assert_eq!(
        error.kind(),
        ErrorKind::InvalidArgument,
        "empty logits are rejected"
    );
    let error = sample_logits(&[0.0, 1.0], 1.0, None).expect_err("rng");
    assert_eq!(
        error.kind(),
        ErrorKind::InvalidArgument,
        "sampled decoding requires RNG state"
    );
    let error = sample_logits(&[f32::NAN, f32::NEG_INFINITY], 1.0, Some(&mut rng_state))
        .expect_err("non-finite");
    assert_eq!(
        error.kind(),
        ErrorKind::Runtime,
        "an all-non-finite distribution is rejected"
    );
    let error = SamplingConfig {
        top_p: -0.01,
        ..SamplingConfig::default()
    }
    .validate()
    .expect_err("config");
    assert_eq!(
        error.kind(),
        ErrorKind::InvalidArgument,
        "invalid sampling controls are rejected"
    );
}

#[test]
fn zero_draw_and_non_finite_candidates() {
    // Inverse xorshift state whose next 53-bit uniform is exactly zero.
    const ZERO_DRAW_STATE: u64 = 0x98d7_6a16_4d99_a710;
    let cold_logits = [-1000.0, 0.0, -1.0];
    let mut s = sampler(
        SamplingConfig {
            seed: 0,
            ..config(1.0)
        },
        &[],
    );
    s.set_rng_state(ZERO_DRAW_STATE);
    assert_eq!(
        s.sample(&cold_logits).expect("sample"),
        1,
        "zero draw must not select underflowed zero probability"
    );
    let masked_logits = [f32::NAN, 4.0, f32::INFINITY, 0.0, f32::NEG_INFINITY];
    for seed in [0, 73, 808] {
        let mut masked = sampler(
            SamplingConfig {
                seed,
                ..config(1.0)
            },
            &[],
        );
        let mut rng = masked.rng_state();
        let expected = build(&masked_logits, masked.config())
            .sample(&mut rng)
            .expect("sample");
        assert_eq!(
            masked.sample(&masked_logits).expect("sample"),
            expected,
            "linear CPU sampling must ignore nonfinite candidates"
        );
    }
}

#[test]
fn strategy_replay_against_reference() {
    let logits = [0.4, 2.0, -1.0, 1.1, -0.3];
    for case in qwen_sampling_cases() {
        for seed in [0, 1, 73, 808] {
            let c = SamplingConfig {
                seed,
                ..case.config.clone()
            };
            let history = [1, 1, 2, 3];
            let mut s = sampler(c.clone(), &history);
            let mut generated: Vec<TokenId> = Vec::new();
            let mut replay = s.clone();
            for _ in 0..16 {
                let distribution =
                    build_distribution(&logits, &c, &history, &generated).expect("distribution");
                let mut ordered: Vec<Probability> = distribution.entries().to_vec();
                if c.top_k == 0 && c.top_p == 1.0 && !(c.min_p > 0.0 && c.min_keep > 1) {
                    ordered.sort_by_key(|entry| entry.token);
                }
                let mut rng = s.rng_state();
                let mut threshold = uniform(&mut rng);
                let mut expected = distribution.best_token().expect("best");
                if c.temperature > 0.0 {
                    for entry in &ordered {
                        if entry.value > 0.0 && threshold < entry.value {
                            expected = entry.token;
                            break;
                        }
                        threshold -= entry.value;
                    }
                }
                let token = s.sample(&logits).expect("sample");
                assert!(
                    token == expected && token == replay.sample(&logits).expect("sample"),
                    "{}",
                    case.name
                );
                generated.push(token);
                s.accept(token).expect("accept");
                replay.accept(token).expect("accept");
            }
        }
    }
}

#[test]
fn filtered_distribution_against_full_sort() {
    let mut logits = vec![0.0f32; 4099];
    let history = [8, 8, 8, 11, 17, 29];
    for concentrated in [false, true] {
        let size = logits.len();
        for (i, logit) in logits.iter_mut().enumerate() {
            *logit = if concentrated {
                -(((i * 73) % size) as f32) * 0.2
            } else {
                (i as f32 * 0.7).sin()
            };
        }
        for case in qwen_sampling_cases() {
            let s = sampler(case.config.clone(), &history);
            let rng = s.rng_state();
            let expected =
                build_distribution(&logits, &case.config, &history, &[]).expect("distribution");
            let actual = s.distribution(&logits).expect("distribution");
            let positive = expected.entries().iter().filter(|e| e.value > 0.0).count();
            assert_eq!(actual.entries().len(), positive, "{}", case.name);
            for entry in expected.entries() {
                assert!(
                    (actual.probability(entry.token) - entry.value).abs() < 1e-12,
                    "{}",
                    case.name
                );
            }
            assert_eq!(
                s.rng_state(),
                rng,
                "materializing probabilities consumes no random draws"
            );
        }
    }
}

#[test]
fn deferred_residual_replay() {
    let logits = [100.0, -100.0, -100.0];
    let mut s = sampler(
        SamplingConfig {
            seed: 7,
            ..config(1.0)
        },
        &[],
    );
    // A retained residual must win over a fresh draw, even one that would
    // almost certainly select another token.
    s.defer_sample(2).expect("defer");
    let rng = s.rng_state();
    let copied = s.clone();
    let mut assigned = SamplerState::default();
    assigned.clone_from(&s);
    let error = s.defer_sample(1).expect_err("duplicate");
    assert_eq!(
        error.kind(),
        ErrorKind::Logic,
        "pending residual cannot be overwritten"
    );
    let mut published = sampler(config(1.0), &[]);
    published.accept(1).expect("accept");
    published.copy_draw_state_from(&s);
    assert_eq!(
        published.history(),
        [1],
        "publishing draw state leaves committed history unchanged"
    );
    let mut states = [s, copied, assigned, published];
    for state in &mut states {
        assert!(
            state.sample(&logits).expect("sample") == 2 && state.rng_state() == rng,
            "copied residual is consumed without another RNG draw"
        );
        assert!(
            state.sample(&logits).expect("sample") == 0 && state.rng_state() != rng,
            "residual is consumed only once"
        );
    }
    let s = &mut states[0];
    s.defer_sample(2).expect("defer");
    s.reset_history(&[]);
    assert_eq!(
        s.sample(&logits).expect("sample"),
        0,
        "new history discards pending residual"
    );
    s.defer_sample(2).expect("defer");
    s.set_rng_state(rng);
    assert_eq!(
        s.sample(&logits).expect("sample"),
        0,
        "RNG reset discards pending residual"
    );
}

#[test]
fn canonical_target_distribution() {
    let mut logits = vec![-1000.0f32; 4099];
    logits[0] = 0.0;
    logits[17] = -1.0;
    logits[4098] = -2.0;
    for case in qwen_sampling_cases() {
        for temperature in [0.5, 0.999_999_94, 2.0] {
            let c = SamplingConfig {
                temperature,
                seed: 19,
                ..case.config.clone()
            };
            let mut s = sampler(c.clone(), &[]);
            for _ in 0..16 {
                let distribution = s.distribution(&logits).expect("distribution");
                let mut rng = s.rng_state();
                let expected = distribution.sample(&mut rng).expect("sample");
                assert!(
                    s.sample(&logits).expect("sample") == expected && s.rng_state() == rng,
                    "AR and verification share exact support, CDF and RNG draws"
                );
                s.accept(expected).expect("accept");
            }
        }
    }
}

#[test]
fn response_penalty_scope() {
    let logits = [3.0, 2.0, 1.0];
    let mut s = sampler(
        SamplingConfig {
            seed: 7,
            repeat_last_n: 0,
            frequency_penalty: 0.5,
            presence_penalty: 0.25,
            ..config(1.0)
        },
        &[0, 0, 0],
    );
    assert_eq!(
        s.distribution(&logits)
            .expect("distribution")
            .best_token()
            .expect("best"),
        0,
        "frequency/presence must not penalize prompt tokens"
    );
    s.accept_tokens(&[0, 0]).expect("accept");
    s.accept_tokens(&[2; 80]).expect("accept");
    let expected = build(&[1.75, 2.0, -39.25], &config(1.0));
    for token in [0, 1, 2] {
        assert!(
            (s.distribution(&logits)
                .expect("distribution")
                .probability(token)
                - expected.probability(token))
            .abs()
                < 1e-12,
            "full response counts must outlive the repetition window"
        );
    }
    let mut rejected = s.clone();
    rejected.accept(1).expect("accept");
    assert!(
        s.distribution(&logits)
            .expect("distribution")
            .best_token()
            .expect("best")
            == 1
            && rejected
                .distribution(&logits)
                .expect("distribution")
                .best_token()
                .expect("best")
                == 0,
        "tentative penalty counts must not leak through speculative rollback"
    );
    let mut replay = s.clone();
    assert_eq!(
        replay.sample(&logits).expect("sample"),
        s.sample(&logits).expect("sample"),
        "penalty copies preserve RNG replay"
    );
    s.reset_history(&[0, 0]);
    assert_eq!(
        s.distribution(&logits)
            .expect("distribution")
            .best_token()
            .expect("best"),
        0,
        "new request resets generated counts"
    );
}

/// The extra filters of the differential scenarios, after the Qwen cases.
fn differential_cases() -> Vec<SamplingCase> {
    let mut cases = qwen_sampling_cases();
    let extra = [
        SamplingCase {
            name: "top-p-wide",
            config: SamplingConfig {
                top_p: 0.95,
                ..config(1.3)
            },
        },
        SamplingCase {
            name: "min-p-linear",
            config: SamplingConfig {
                min_p: 0.05,
                ..config(1.0)
            },
        },
        SamplingCase {
            name: "min-p-keep",
            config: SamplingConfig {
                min_p: 0.2,
                min_keep: 4,
                ..config(0.9)
            },
        },
        SamplingCase {
            name: "top-k-wide",
            config: SamplingConfig {
                top_k: 300,
                top_p: 0.9,
                ..config(0.7)
            },
        },
        SamplingCase {
            name: "penalties-all",
            config: SamplingConfig {
                repeat_penalty: 1.3,
                repeat_last_n: 8,
                frequency_penalty: 0.3,
                presence_penalty: 0.2,
                ..config(1.0)
            },
        },
    ];
    for mut case in extra {
        case.config.seed = 73;
        cases.push(case);
    }
    cases
}

/// `Row` of the harness: an LCG in float arithmetic, NaN and infinities
/// planted in rows longer than 12.
fn row(seed: u64, size: usize, scale: f32) -> Vec<f32> {
    let mut state = seed.wrapping_mul(2).wrapping_add(1);
    let mut row: Vec<f32> = (0..size)
        .map(|_| {
            state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            ((state >> 40) as f32 / 16_777_216.0 * 8.0 - 4.0) * scale
        })
        .collect();
    if size > 12 {
        row[3] = f32::NAN;
        row[7] = f32::INFINITY;
        row[11] = f32::NEG_INFINITY;
    }
    row
}

/// FNV-1a over distribution entries, as the harness.
struct Digest(u64);

impl Digest {
    fn word(&mut self, word: u64, bytes: usize) {
        for i in 0..bytes {
            self.0 = (self.0 ^ ((word >> (8 * i)) & 0xff)).wrapping_mul(0x0100_0000_01b3);
        }
    }

    fn distribution(&mut self, distribution: &SamplingDistribution) {
        self.word(distribution.entries().len() as u64, 8);
        for entry in distribution.entries() {
            self.word(u64::from(entry.token), 4);
            self.word(entry.value.to_bits(), 8);
        }
    }
}

fn differential_scenarios() -> Vec<String> {
    let history = [1, 1, 2, 3, 9, 9];
    let mut lines = Vec::new();
    for size in [5usize, 2048, 4099] {
        for scale in [1.0f32, 6.0] {
            for case in differential_cases() {
                for own_seed in [true, false] {
                    let mut c = case.config.clone();
                    if !own_seed {
                        c.seed = 5;
                    }
                    let mut s = sampler(c.clone(), &history);
                    let mut digest = Digest(0xcbf2_9ce4_8422_2325);
                    let mut tokens = Vec::new();
                    let mut generated = Vec::new();
                    let row_base = size as u64 * 131 + (scale * 7.0) as u64 * 17;
                    for step in 0..10u64 {
                        let logits = row(row_base + step, size, scale);
                        if step % 3 == 0 {
                            digest.distribution(&s.distribution(&logits).expect("distribution"));
                        }
                        let token = s.sample(&logits).expect("sample");
                        tokens.push(token.to_string());
                        generated.push(token);
                        s.accept(token).expect("accept");
                    }
                    let first = row(size as u64 * 131 + 3, size, scale);
                    digest.distribution(
                        &build_distribution(&first, &c, &history, &generated)
                            .expect("distribution"),
                    );
                    if size >= 8 {
                        digest.distribution(
                            &s.distribution_compact(&first[..8], &[10, 1, 9, 2, 3, 12, 40, 41])
                                .expect("distribution"),
                        );
                    }
                    let mut residual = String::new();
                    if c.temperature > 0.0 {
                        let mut draft = sampler(c.clone(), &[]);
                        let ids = [0, 1, 2, 4, 1];
                        let probabilities = [0.5, 0.125, 0.125, 0.125, 0.125];
                        let mut drawn = Vec::new();
                        for step in 0..5u64 {
                            let logits = row(size as u64 + 1000 + step, size, scale);
                            let token = if step == 2 {
                                draft.defer_sample(4).expect("defer");
                                draft.sample(&logits)
                            } else {
                                draft.sample_residual(&logits, &ids, &probabilities)
                            };
                            drawn.push(token.expect("sample").to_string());
                        }
                        residual = format!("{} rng={:016x}", drawn.join(","), draft.rng_state());
                    }
                    lines.push(format!(
                        "{}/{size}/{}/{} tokens={} rng={:016x} digest={:016x} residual={residual}",
                        case.name,
                        scale as i32,
                        c.seed,
                        tokens.join(","),
                        s.rng_state(),
                        digest.0,
                    ));
                }
            }
        }
    }
    lines
}

#[test]
fn matches_the_cpp_sampler_bit_for_bit() {
    let fixture: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/sampling_cpp.json")).expect("fixture");
    let expected: Vec<&str> = fixture["lines"]
        .as_array()
        .expect("lines")
        .iter()
        .map(|line| line.as_str().expect("line"))
        .collect();
    let actual = differential_scenarios();
    assert_eq!(actual.len(), expected.len(), "scenario count");
    let mismatches: Vec<(&str, &String)> = expected
        .iter()
        .zip(&actual)
        .filter(|(e, a)| *e != a)
        .map(|(e, a)| (*e, a))
        .collect();
    assert!(
        mismatches.is_empty(),
        "{} of {} scenarios differ, first: {:?}",
        mismatches.len(),
        expected.len(),
        mismatches.first()
    );
}

/// Top-p zero keeps the most probable token, or `min_keep` of them
///.
#[test]
fn top_p_zero_keeps_the_minimum() {
    for floor in [0, 1, 2] {
        let config = SamplingConfig {
            temperature: 1.0,
            top_p: 0.0,
            min_keep: floor,
            ..SamplingConfig::default()
        };
        config.validate().expect("top-p zero is valid");
        let zero = build_distribution(&[2.0, 1.0, 0.0], &config, &[], &[]).expect("distribution");
        assert_eq!(zero.entries().len(), floor.max(1));
        assert_eq!(zero.best_token().expect("best"), 0);
    }
}

/// The sparse penalty walk of greedy selection matches an independent
/// distribution build.
#[test]
fn greedy_sparse_penalty_walk() {
    let mut logits: Vec<f32> = (0..16385)
        .map(|i| ((i * 7919) % 65521 - 32768) as f32 / 32768.0)
        .collect();
    logits[0] = f32::NAN;
    logits[128] = f32::NAN;
    logits[777] = f32::INFINITY;
    for repeat in [0.7, 1.0, 1.3] {
        for penalty in [-1.5f32, 1.5] {
            let config = SamplingConfig {
                seed: 73,
                repeat_penalty: repeat,
                repeat_last_n: 3,
                frequency_penalty: penalty / 3.0,
                presence_penalty: penalty,
                ..SamplingConfig::default()
            };
            let history = [0, 128, 777, 16384, TokenId::MAX];
            let mut sampler = SamplerState::new(config.clone(), &history).expect("sampler");
            let mut generated = Vec::new();
            for step in 0..16u32 {
                let expected = build_distribution(&logits, &config, &history, &generated)
                    .expect("distribution")
                    .best_token()
                    .expect("best");
                assert_eq!(sampler.sample(&logits).expect("sample"), expected);
                let token = if step % 3 == 0 {
                    128
                } else {
                    (step * 977) % logits.len() as u32
                };
                generated.push(token);
                sampler.accept(token).expect("accept");
            }
        }
    }
}

/// Large rows exercise block skipping: ties straddling the top-k boundary,
/// non-finite entries and penalties that lift a low token into the set
///.
#[test]
fn block_skipped_top_k_against_full_sort() {
    let mut logits: Vec<f32> = (0..70001)
        .map(|i| ((i as f32 * 0.37).sin() * 8.0).floor())
        .collect();
    logits[5] = f32::NAN;
    logits[640] = f32::INFINITY;
    logits[641] = f32::NEG_INFINITY;
    logits[69999] = 9.0;
    let history: [TokenId; 7] = [3, 700, 701, 33333, 50000, 69999, 70000];
    let configs = [
        SamplingConfig {
            temperature: 1.0,
            top_k: 64,
            top_p: 0.95,
            ..SamplingConfig::default()
        },
        SamplingConfig {
            temperature: 1.0,
            top_k: 1,
            ..SamplingConfig::default()
        },
        SamplingConfig {
            temperature: 0.7,
            top_k: 300,
            ..SamplingConfig::default()
        },
        SamplingConfig {
            temperature: 1.0,
            top_k: 64,
            repeat_penalty: 1.3,
            presence_penalty: -9.0,
            ..SamplingConfig::default()
        },
        SamplingConfig {
            temperature: 0.8,
            top_k: 20,
            repeat_penalty: 0.5,
            frequency_penalty: 2.0,
            ..SamplingConfig::default()
        },
    ];
    for config in configs {
        let mut sampler = SamplerState::new(config.clone(), &history).expect("sampler");
        sampler.accept_tokens(&history[..3]).expect("accept");
        let expected =
            build_distribution(&logits, &config, &history, &history[..3]).expect("distribution");
        let actual = sampler.distribution(&logits).expect("distribution");
        assert_eq!(actual.entries().len(), expected.entries().len());
        for entry in expected.entries() {
            assert!((actual.probability(entry.token) - entry.value).abs() < 1e-12);
        }
    }
}

/// Host sampling time per row over the Qwen3.8 vocabulary for the thinking
/// preset, the non-thinking preset with a 300-token history, and greedy with
/// penalties:
///   cargo test --release -p gufo-core --test sampling sampler_speed -- --ignored --nocapture
#[test]
#[ignore = "timing"]
fn sampler_speed() {
    let vocabulary = 248_320;
    let logits: Vec<f32> = (0..vocabulary)
        .map(|i| ((i as f32 * 0.37).sin() * 6.0) + ((i * 7919) % 65521) as f32 / 65521.0)
        .collect();
    let history: Vec<TokenId> = (0..300)
        .map(|i| (i * 7919 + 13) % vocabulary as u32)
        .collect();
    for (name, config, history) in [
        (
            "thinking",
            SamplingConfig {
                temperature: 1.0,
                top_k: 20,
                top_p: 0.95,
                seed: 7,
                ..SamplingConfig::default()
            },
            &[][..],
        ),
        (
            "non-thinking+300",
            SamplingConfig {
                temperature: 0.7,
                top_k: 20,
                top_p: 0.8,
                presence_penalty: 1.5,
                seed: 7,
                ..SamplingConfig::default()
            },
            &history[..],
        ),
        (
            "greedy+penalties",
            SamplingConfig {
                presence_penalty: 1.5,
                ..SamplingConfig::default()
            },
            &history[..],
        ),
    ] {
        let mut sampler = SamplerState::new(config, &[]).expect("sampler");
        sampler.accept_tokens(history).expect("accept");
        let rounds = 400;
        let start = std::time::Instant::now();
        let mut sink = 0u64;
        for _ in 0..rounds {
            sink += u64::from(sampler.clone().sample(&logits).expect("sample"));
        }
        let per_row = start.elapsed().as_secs_f64() * 1e6 / f64::from(rounds);
        println!("{name}: {per_row:.1} us per row ({sink})");
    }
}

/// A compact target row (the top-k union with every penalized token, in any
/// order) gives the full row's distribution bit for bit, and selections it
/// cannot represent are refused (`TestCompactTargetContract`).
#[test]
fn compact_target_contract() {
    let logits = [0.0f32, 0.75, -1.0, 0.75, 3.0, 0.1];
    // Deliberately unordered IDs. A frequency penalty can promote a token
    // whose raw logit is far below the original top-k.
    let candidates = [
        LogitCandidate {
            token: 4,
            value: 3.0,
        },
        LogitCandidate {
            token: 2,
            value: -1.0,
        },
        LogitCandidate {
            token: 3,
            value: 0.75,
        },
        LogitCandidate {
            token: 1,
            value: 0.75,
        },
    ];
    let config = SamplingConfig {
        temperature: 0.7,
        top_k: 2,
        top_p: 0.8,
        frequency_penalty: -5.0,
        ..SamplingConfig::default()
    };
    let mut state = sampler(config.clone(), &[]);
    state.accept(2).expect("accept");
    let expected = state.distribution(&logits).expect("full row");
    let actual = state
        .distribution_from_candidates(&candidates)
        .expect("compact row");
    assert_eq!(
        expected.entries().len(),
        actual.entries().len(),
        "compact target retains full top-k support"
    );
    for (e, a) in expected.entries().iter().zip(actual.entries()) {
        assert!(
            e.token == a.token && e.value.to_bits() == a.value.to_bits(),
            "compact target retains exact FP64 probabilities"
        );
    }
    for mode in 0..3 {
        let mut unsupported = config.clone();
        match mode {
            0 => unsupported.temperature = 0.0,
            1 => unsupported.top_k = 0,
            _ => {
                unsupported.reasoning_budget = Some(Arc::new(ReasoningBudget {
                    tokens: 0,
                    forced: vec![3],
                    ends: vec![3],
                    prompt: Vec::new(),
                    partial_utf8: None,
                }));
            }
        }
        let refused = sampler(unsupported, &[]).distribution_from_candidates(&candidates);
        assert!(
            refused.is_err_and(|e| e.kind() == ErrorKind::InvalidArgument),
            "compact target refuses unsupported selection semantics"
        );
    }
}
